28	pub fn cascade_action(kind: DepKind, coverage: Coverage, source: Severity, cfg: &CascadeConfig) -> CascadeDecision {
29	    use Coverage::*;
30	    use DepKind::*;
31	
32	    let effective = match (cfg.mode, coverage) {
33	        (CascadeMode::Always, _) => DoesNotCover,
34	        (CascadeMode::OutOfRange, Covers) => Covers,
35	        (CascadeMode::OutOfRange, DoesNotCover) => DoesNotCover,
36	        (CascadeMode::OutOfRange, Unknown) => Covers,
37	    };
38	
39	    let rewrite = matches!(coverage, DoesNotCover);
40	
41	    let (severity, governed_by, escalated) = match (kind, effective) {
42	        (Runtime | Optional | Build, Covers) => (Severity::None, None, false),
43	        (Runtime | Optional | Build, DoesNotCover) => (
44	            cfg.bump_severity.as_severity(),
45	            Some(ConfigKey::CASCADE_BUMP_SEVERITY),
46	            false,
47	        ),
48	        (Peer, Covers) => (Severity::None, None, false),
49	        (Peer, DoesNotCover)
50	            if cfg.peer_escalation
51	                && matches!(coverage, DoesNotCover)
52	                && matches!(source, Severity::Minor | Severity::Major) =>
53	        {
54	            (Severity::Major, Some(ConfigKey::CASCADE_PEER_ESCALATION), true)
55	        }
56	        (Peer, DoesNotCover) => (
57	            cfg.bump_severity.as_severity(),
58	            Some(ConfigKey::CASCADE_BUMP_SEVERITY),
59	            false,
60	        ),
61	        _ => (Severity::None, None, false),
62	    };
63	
64	    let governed_by = match (cfg.mode, coverage, severity) {
65	        (CascadeMode::Always, Covers | Unknown, s) if s != Severity::None => Some(ConfigKey::CASCADE_MODE),
66	        _ => governed_by,
67	    };
68	
69	    CascadeDecision {
70	        severity,
71	        rewrite,
72	        governed_by,
73	        escalated,
74	        unknown_coverage: matches!(coverage, Unknown),
75	    }
76	}
