78	pub fn coverage(spec: &DepSpec, new: &Version) -> Result<Coverage, GrammarMismatch> {
79	    match spec {
80	        DepSpec::Exact(v) => {
81	            if v == new {
82	                Ok(Coverage::Covers)
83	            } else {
84	                Ok(Coverage::DoesNotCover)
85	            }
86	        }
87	        DepSpec::CargoBare(v) => {
88	            if caret_covers(v, new)? {
89	                Ok(Coverage::Covers)
90	            } else {
91	                Ok(Coverage::DoesNotCover)
92	            }
93	        }
94	        DepSpec::Range(req, _) => {
95	            if req.matches(new)? {
96	                Ok(Coverage::Covers)
97	            } else {
98	                Ok(Coverage::DoesNotCover)
99	            }
100	        }
101	        DepSpec::Workspace(_) => Ok(Coverage::Covers),
102	        DepSpec::WorkspaceProtocol(workspace) => workspace.coverage(new),
103	        DepSpec::Catalog(_) | DepSpec::Opaque(_) => Ok(Coverage::Unknown),
104	    }
105	}
