107	pub(crate) fn caret_covers(cur: &Version, new: &Version) -> Result<bool, GrammarMismatch> {
108	    let cmp = Version::compare(new, cur)?;
109	    if cmp.is_lt() {
110	        return Ok(false);
111	    }
112	    // A caret requirement always matches the version it names, pre-release or not.
113	    if new == cur {
114	        return Ok(true);
115	    }
116	    // A pre-release is never covered by a caret range (^1.2.3 does not cover 1.9.0-alpha.1).
117	    if new.is_prerelease() {
118	        return Ok(false);
119	    }
120	    let cur_maj = cur.major().unwrap_or(0);
121	    let cur_min = cur.minor().unwrap_or(0);
122	    let new_maj = new.major().unwrap_or(0);
123	    let new_min = new.minor().unwrap_or(0);
124	
125	    if cur_maj > 0 {
126	        Ok(new_maj == cur_maj)
127	    } else if cur_min > 0 {
128	        Ok(new_maj == 0 && new_min == cur_min)
129	    } else {
130	        Ok(new == cur)
131	    }
132	}
