168	pub(crate) fn dependency_rewrite_key(edge: &DepEdge) -> RewriteKey {
169	    RewriteKey {
170	        target: if edge.inherited {
171	            DepWriteTarget::CargoWorkspaceDependency {
172	                root_manifest: edge.from_manifest.clone(),
173	            }
174	        } else {
175	            DepWriteTarget::Manifest(edge.from_manifest.clone())
176	        },
177	        name: edge.name.clone(),
178	        kind: if edge.inherited { None } else { Some(edge.kind) },
179	        // An inherited declaration is rewritten once, in the workspace root, whichever member table names it.
180	        locator: if edge.inherited {
181	            DepLocator::default()
182	        } else {
183	            edge.locator.clone()
184	        },
185	    }
186	}
