188	/// Propagates `input.seed`'s severities outward to dependents until no
189	/// target version changes, or `convergence_bound`'s iteration cap is
190	/// exceeded ([`GraphError::CascadeNotConverged`]) -- turns a would-be
191	/// infinite loop into a reportable bug, bound derived from package count.
192	///
193	/// One pass: pop a package, compute its bumped target, walk every
194	/// dependent edge, apply [`cascade_action`] to decide if that dependent's
195	/// severity/target changes and gets re-queued.
196	///
197	/// A genuine cross-grammar coverage failure (`coverage`'s `Err`, e.g.
198	/// SemVer target vs. PEP440 spec) aborts the whole cascade with
199	/// `Err(GraphError::GrammarMismatch)`. Soft instead: `Catalog`/`Opaque`
200	/// specs never have coverage tested (`coverage` returns `Unknown`
201	/// unconditionally), so they can't block anything -- `Catalog` gets
202	/// [`DiagnosticCode::CatalogSpecNotRewritten`], `Opaque` gets no
203	/// diagnostic. [`DiagnosticCode::RangeNotRoundTrippable`]'s real trigger
204	/// is a different step: `rewrite_spec`, when a mechanical range rewrite
205	/// (not a coverage test) fails on an otherwise-known-coverage spec.
206	pub fn solve_cascade<D: DependencyResolver>(input: CascadeInput<'_, D>) -> Result<CascadeOutcome, GraphError> {
207	    let mut out = CascadeOutcome {
208	        severities: input.seed.clone(),
209	        reasons: input.reasons.clone(),
210	        ..Default::default()
211	    };
212	
213	    // Provisional: the loop below may still move them, so nothing here may rewrite a range from them.
214	    let mut targets: BTreeMap<PackageId, Version> = BTreeMap::new();
215	    for (id, &sev) in input.seed {
216	        let t = bump_target(id, sev, &input)?;
217	        targets.insert(id.clone(), t);
218	    }
219	
220	    let mut worklist: BTreeSet<PackageId> = targets.keys().cloned().collect();
221	    let mut iterations = 0;
222	    let bound = convergence_bound(input.graph.packages().count());
223	    // Edges already run through rewrite_spec, so the floor-raise pass below doesn't re-diagnose them.
224	    let mut rewrite_attempted: BTreeSet<RewriteKey> = BTreeSet::new();
225	
226	    let mut changed = true;
227	    while changed {
228	        changed = false;
229	
230	        while let Some(pkg) = worklist.pop_first() {
231	            iterations += 1;
232	            if iterations > bound {
233	                return Err(GraphError::CascadeNotConverged { iterations });
234	            }
235	
236	            let new_version = targets[&pkg].clone();
237	            let src_sev = out.severities[&pkg];
238	
239	            let dependents: Vec<DepEdge> = input.graph.dependents_of(&pkg).cloned().collect();
240	            for edge in dependents {
241	                let cov = coverage(&edge.spec, &new_version).map_err(|source| GraphError::GrammarMismatch {
242	                    from: edge.from.clone(),
243	                    to: edge.to.clone(),
244	                    source,
245	                })?;
246	
247	                let d = cascade_action(edge.kind, cov, src_sev, input.cfg);
248	
249	                if d.unknown_coverage && !matches!(edge.spec, DepSpec::Opaque(_)) {
250	                    let code = match edge.spec {
251	                        DepSpec::Catalog(_) => DiagnosticCode::CatalogSpecNotRewritten,
252	                        _ => DiagnosticCode::RangeNotRoundTrippable,
253	                    };
254	                    out.diagnostics.push(Diagnostic {
255	                        code,
256	                        severity: DiagnosticSeverity::Warning,
257	                        message: format!(
258	                            "spec `{}` for `{}` could not be tested for coverage",
259	                            edge.spec.render(),
260	                            edge.to.display_name()
261	                        ),
262	                        package: Some(edge.from.clone()),
263	                        path: Some(edge.from_manifest.clone()),
264	                        governed_by: Some(ConfigKey::CASCADE_PRESERVE_NPM_RANGES),
265	                        escalated_by: None,
266	                    });
267	                }
268	
269	                let cur_sev = out.severities.get(&edge.from).copied().unwrap_or(Severity::None);
270	                if d.severity > cur_sev {
271	                    raise(
272	                        &edge.from,
273	                        d.severity,
274	                        &d,
275	                        &pkg,
276	                        &edge,
277	                        &new_version,
278	                        &mut out,
279	                        &mut targets,
280	                        input.groups,
281	                        &mut worklist,
282	                        &input,
283	                    )?;
284	                }
285	            }
286	        }
287	
288	        // Linked group release severity propagation
289	        for g in input.groups.linked.values() {
290	            let max_sev = g.max_severity(&out.severities);
291	            if max_sev == Severity::None {
292	                continue;
293	            }
294	
295	            // Skip members absent from `input.base`: `bump_target` would hit `MissingField`.
296	            let mut live_members = Vec::new();
297	            for id in g.package_members() {
298	                if !input.base.contains_key(id) {
299	                    out.diagnostics.push(Diagnostic {
300	                        code: DiagnosticCode::UnknownPackage,
301	                        severity: DiagnosticSeverity::Warning,
302	                        message: format!(
303	                            "Linked group `{}` references package `{}` which is not in the \
304	                             workspace; the stale group member is skipped. Remove it from \
305	                             callisto.toml to silence this warning.",
306	                            g.name,
307	                            id.display_name()
308	                        ),
309	                        package: Some(id.clone()),
310	                        path: None,
311	                        governed_by: Some(ConfigKey::LINKED_GROUP),
312	                        escalated_by: None,
313	                    });
314	                    continue;
315	                }
316	                live_members.push(id.clone());
317	                let cur_sev = out.severities.get(id).copied().unwrap_or(Severity::None);
318	                if max_sev > cur_sev {
319	                    out.severities.insert(id.clone(), max_sev);
320	                }
321	            }
322	
323	            let mut winner: Option<Version> = None;
324	            for id in &live_members {
325	                let candidate = bump_target(id, max_sev, &input)?;
326	                winner = Some(match winner {
327	                    None => candidate,
328	                    Some(best) => {
329	                        let cmp = Version::compare(&candidate, &best).map_err(|_grammar_mismatch| {
330	                            GraphError::GroupGrammarMismatch {
331	                                group: g.name.clone(),
332	                                members: live_members
333	                                    .iter()
334	                                    .filter_map(|m| targets.get(m).map(|v| (m.clone(), v.clone())))
335	                                    .collect(),
336	                            }
337	                        })?;
338	                        if cmp.is_gt() {
339	                            candidate
340	                        } else {
341	                            best
342	                        }
343	                    }
344	                });
345	            }
346	            let Some(winner) = winner else { continue };
347	
348	            for id in live_members {
349	                if targets.get(&id) != Some(&winner) {
350	                    targets.insert(id.clone(), winner.clone());
351	                    out.reasons
352	                        .insert(id.clone(), BumpReason::LinkedGroupUnion { group: g.name.clone() });
353	                    worklist.insert(id.clone());
354	                    changed = true;
355	                }
356	            }
357	        }
358	
359	        // Fixed groups converge on `fixed_group_target`, not the max of per-member candidates.
360	        for g in input.groups.fixed.values() {
361	            let max_sev = g.max_severity(&out.severities);
362	            if max_sev == Severity::None {
363	                continue;
364	            }
365	
366	            // Skip members absent from `input.base`: they would reach `out.severities` and panic in `plan_version`.
367	            let mut live_members = Vec::new();
368	            for id in g.package_members() {
369	                if !input.base.contains_key(id) {
370	                    out.diagnostics.push(Diagnostic {
371	                        code: DiagnosticCode::UnknownPackage,
372	                        severity: DiagnosticSeverity::Warning,
373	                        message: format!(
374	                            "Fixed group `{}` references package `{}` which is not in the \
375	                             workspace; the stale group member is skipped. Remove it from \
376	                             callisto.toml to silence this warning.",
377	                            g.name,
378	                            id.display_name()
379	                        ),
380	                        package: Some(id.clone()),
381	                        path: None,
382	                        governed_by: Some(ConfigKey::FIXED_GROUP),
383	                        escalated_by: None,
384	                    });
385	                    continue;
386	                }
387	                live_members.push(id.clone());
388	                let cur_sev = out.severities.get(id).copied().unwrap_or(Severity::None);
389	                if max_sev > cur_sev {
390	                    out.severities.insert(id.clone(), max_sev);
391	                }
392	            }
393	
394	            let winner =
395	                crate::groups::fixed_group_target(&g.name, &live_members, input.base, max_sev, input.tags, input.pre)?;
396	
397	            for id in live_members {
398	                if targets.get(&id) != Some(&winner) {
399	                    targets.insert(id.clone(), winner.clone());
400	                    out.reasons
401	                        .insert(id.clone(), BumpReason::FixedGroupUnion { group: g.name.clone() });
402	                    worklist.insert(id.clone());
403	                    changed = true;
404	                }
405	            }
406	        }
407	    }
408	
409	    out.targets = ConvergedTargets::settle(targets);
410	
411	    // A fixed group can realign `via` after the step that recorded the reason, so name the version that is released.
412	    for reason in out.reasons.values_mut() {
413	        if let BumpReason::Cascade { via, dependency_to, .. } = reason
414	            && let Some(settled) = out.targets.get(via)
415	        {
416	            *dependency_to = settled.version().clone();
417	        }
418	    }
419	
420	    // Group alignment can move a target after the worklist first visited it, so rewrites and rejections are derived
421	    // from the converged targets only.
422	    for (pkg, new_version) in out.targets.iter() {
423	        let src_sev = out.severities[pkg];
424	        for edge in input.graph.dependents_of(pkg) {
425	            let cov = coverage(&edge.spec, new_version.version()).map_err(|source| GraphError::GrammarMismatch {
426	                from: edge.from.clone(),
427	                to: edge.to.clone(),
428	                source,
429	            })?;
430	            let d = cascade_action(edge.kind, cov, src_sev, input.cfg);
431	
432	            if d.rewrite || d.severity > Severity::None {
433	                out.dependency_updates
434	                    .entry(edge.from.clone())
435	                    .or_default()
436	                    .insert(edge.to.clone(), edge.kind);
437	            }
438	
439	            if d.rewrite {
440	                match rewrite_edge(edge, new_version, input.cfg)? {
441	                    RewriteOutcome::Rewritten(to_spec) => {
442	                        let key = dependency_rewrite_key(edge);
443	                        rewrite_attempted.insert(key.clone());
444	                        out.rewrites.insert(
445	                            key.clone(),
446	                            SpecRewrite {
447	                                key,
448	                                dependency: edge.to.clone(),
449	                                from: edge.spec.clone(),
450	                                to: to_spec,
451	                            },
452	                        );
453	                    }
454	                    RewriteOutcome::LeftAlone(dg) => {
455	                        rewrite_attempted.insert(dependency_rewrite_key(edge));
456	                        out.diagnostics.push(dg);
457	                    }
458	                }
459	            }
460	        }
461	    }
462	
463	    // A releasing package's floor on a co-released dependency is always raised, even when the old spec still covers it.
464	    for pkg in out.severities.keys().cloned().collect::<Vec<_>>() {
465	        let deps: Vec<DepEdge> = input.graph.dependencies_of(&pkg).cloned().collect();
466	        for edge in deps {
467	            if edge.kind == DepKind::Dev {
468	                continue;
469	            }
470	            if matches!(
471	                edge.spec,
472	                DepSpec::Workspace(_) | DepSpec::Catalog(_) | DepSpec::Opaque(_)
473	            ) {
474	                continue;
475	            }
476	            let Some(new_version) = out.targets.get(&edge.to) else {
477	                continue;
478	            };
479	            if matches!(edge.spec, DepSpec::WorkspaceProtocol(_))
480	                && coverage(&edge.spec, new_version.version()).map_err(|source| GraphError::GrammarMismatch {
481	                    from: edge.from.clone(),
482	                    to: edge.to.clone(),
483	                    source,
484	                })? != Coverage::DoesNotCover
485	            {
486	                continue;
487	            }
488	
489	            let key = dependency_rewrite_key(&edge);
490	            if rewrite_attempted.contains(&key) {
491	                continue;
492	            }
493	
494	            // A floor that cannot be raised (`*`, a bare Python requirement, `||` sets) is harmless while it covers.
495	            if matches!(coverage(&edge.spec, new_version.version()), Ok(Coverage::Covers))
496	                && matches!(
497	                    rewrite_spec(
498	                        &edge.spec,
499	                        new_version,
500	                        manifest_ecosystem(&edge.from_manifest),
501	                        input.cfg
502	                    ),
503	                    RewriteOutcome::LeftAlone(_)
504	                )
505	            {
506	                continue;
507	            }
508	
509	            match rewrite_edge(&edge, new_version, input.cfg)? {
510	                RewriteOutcome::Rewritten(to_spec) => {
511	                    out.rewrites.entry(key.clone()).or_insert_with(|| SpecRewrite {
512	                        key,
513	                        dependency: edge.to.clone(),
514	                        from: edge.spec.clone(),
515	                        to: to_spec,
516	                    });
517	                }
518	                RewriteOutcome::LeftAlone(dg) => {
519	                    out.diagnostics.push(dg);
520	                }
521	            }
522	        }
523	    }
524	
525	    Ok(out)
526	}
