528	fn bump_target<D: DependencyResolver>(
529	    id: &PackageId,
530	    sev: Severity,
531	    input: &CascadeInput<'_, D>,
532	) -> Result<Version, GraphError> {
533	    // A fixed-group member's own bump is never visible: its target is always the group's aligned version.
534	    if let Some(group) = input.groups.fixed_group_of(id) {
535	        let live: Vec<PackageId> = group
536	            .package_members()
537	            .filter(|member| input.base.contains_key(*member))
538	            .cloned()
539	            .collect();
540	        if !live.is_empty() {
541	            return crate::groups::fixed_group_target(&group.name, &live, input.base, sev, input.tags, input.pre);
542	        }
543	    }
544	
545	    let base = input.base.get(id).cloned().ok_or_else(|| {
546	        GraphError::Manifest(callisto_model::ManifestError::MissingField {
547	            path: PathBuf::from(id.name()),
548	            field: "version",
549	        })
550	    })?;
551	
552	    // PreMode::Exit falls through to a plain `versioning.bump`, which strips a matching pre-release tag directly.
553	    crate::groups::versioned_bump(id, &base, sev, input.pre)
554	}
