556	#[allow(clippy::too_many_arguments)]
557	fn raise<D: DependencyResolver>(
558	    pkg: &PackageId,
559	    sev: Severity,
560	    decision: &CascadeDecision,
561	    via: &PackageId,
562	    edge: &DepEdge,
563	    dependency_to: &Version,
564	    out: &mut CascadeOutcome,
565	    targets: &mut BTreeMap<PackageId, Version>,
566	    groups: &GroupTable,
567	    worklist: &mut BTreeSet<PackageId>,
568	    input: &CascadeInput<'_, D>,
569	) -> Result<bool, GraphError> {
570	    let cur_sev = out.severities.get(pkg).copied().unwrap_or(Severity::None);
571	    if sev <= cur_sev {
572	        return Ok(false);
573	    }
574	
575	    out.severities.insert(pkg.clone(), sev);
576	
577	    let new_reason = if decision.escalated {
578	        BumpReason::PeerEscalation {
579	            via: via.clone(),
580	            spec: edge.spec.render(),
581	        }
582	    } else {
583	        BumpReason::Cascade {
584	            via: via.clone(),
585	            dep_kind: edge.kind,
586	            spec: edge.spec.render(),
587	            dependency_to: dependency_to.clone(),
588	        }
589	    };
590	    out.reasons.insert(pkg.clone(), new_reason);
591	
592	    if let Some(ref gov) = decision.governed_by {
593	        out.governed_by.insert(pkg.clone(), gov.clone());
594	    }
595	
596	    let new_t = bump_target(pkg, sev, input)?;
597	    targets.insert(pkg.clone(), new_t);
598	    worklist.insert(pkg.clone());
599	
600	    for sib in groups.fixed_siblings(pkg) {
601	        let sib_sev = out.severities.get(sib).copied().unwrap_or(Severity::None);
602	        if sev > sib_sev {
603	            out.severities.insert(sib.clone(), sev);
604	            out.reasons.insert(
605	                sib.clone(),
606	                BumpReason::FixedGroupUnion {
607	                    group: groups
608	                        .fixed_group_of(pkg)
609	                        .expect("a fixed-group sibling implies the package has a fixed group")
610	                        .name
611	                        .clone(),
612	                },
613	            );
614	            let sib_t = bump_target(sib, sev, input)?;
615	            targets.insert(sib.clone(), sib_t);
616	            worklist.insert(sib.clone());
617	        }
618	    }
619	
620	    Ok(true)
621	}
622	
623	/// Each dependency range that excludes its package's snapshot version, rewritten; a snapshot has no cascade or groups.
624	pub(crate) fn snapshot_rewrites<D: DependencyResolver>(
625	    graph: &D,
626	    versions: BTreeMap<PackageId, Version>,
627	    cfg: &CascadeConfig,
628	) -> Result<(Vec<SpecRewrite>, Vec<Diagnostic>), GraphError> {
629	    let settled = ConvergedTargets::settle(versions);
630	    let mut rewrites: BTreeMap<RewriteKey, SpecRewrite> = BTreeMap::new();
631	    let mut diagnostics = Vec::new();
632	
633	    for pkg in graph.packages() {
634	        for edge in graph.dependencies_of(&pkg.id) {
635	            if matches!(edge.spec, DepSpec::Workspace(_) | DepSpec::Catalog(_)) {
636	                if matches!(edge.spec, DepSpec::Catalog(_)) {
637	                    diagnostics.push(Diagnostic {
638	                        code: DiagnosticCode::CatalogSpecNotRewritten,
639	                        severity: DiagnosticSeverity::Warning,
640	                        message: format!(
641	                            "spec `{}` for `{}` could not be tested for coverage",
642	                            edge.spec.render(),
643	                            edge.to.display_name()
644	                        ),
645	                        package: Some(edge.from.clone()),
646	                        path: Some(edge.from_manifest.clone()),
647	                        governed_by: Some(ConfigKey::CASCADE_PRESERVE_NPM_RANGES),
648	                        escalated_by: None,
649	                    });
650	                }
651	                continue;
652	            }
653	            if matches!(edge.spec, DepSpec::Opaque(_)) {
654	                continue;
655	            }
656	            let Some(snap_to) = settled.get(&edge.to) else {
657	                continue;
658	            };
659	            // A spec in another grammar than the snapshot version surfaces as a GrammarMismatch, not silently.
660	            let covers = coverage(&edge.spec, snap_to.version()).map_err(|source| GraphError::GrammarMismatch {
661	                from: edge.from.clone(),
662	                to: edge.to.clone(),
663	                source,
664	            })?;
665	            if matches!(covers, Coverage::Covers) {
666	                continue;
667	            }
668	
669	            match rewrite_edge(edge, snap_to, cfg)? {
670	                RewriteOutcome::Rewritten(to_spec) => {
671	                    let key = dependency_rewrite_key(edge);
672	                    rewrites.entry(key.clone()).or_insert_with(|| SpecRewrite {
673	                        key,
674	                        dependency: edge.to.clone(),
675	                        from: edge.spec.clone(),
676	                        to: to_spec,
677	                    });
678	                }
679	                RewriteOutcome::LeftAlone(dg) => {
680	                    diagnostics.push(dg);
681	                }
682	            }
683	        }
684	    }
685	    Ok((rewrites.into_values().collect(), diagnostics))
686	}
687	
688	pub(crate) fn convergence_bound(package_count: usize) -> usize {
689	    4 * package_count + 1
690	}
