692	#[derive(Clone, Debug, PartialEq, Eq, PartialOrd, Ord)]
693	pub enum DepWriteTarget {
694	    Manifest(PathBuf),
695	    CargoWorkspaceDependency { root_manifest: PathBuf },
696	}
697	
698	#[derive(Clone, Debug, PartialEq, Eq, PartialOrd, Ord)]
699	pub struct RewriteKey {
700	    pub target: DepWriteTarget,
701	    pub name: String,
702	    pub kind: Option<DepKind>,
703	    pub locator: DepLocator,
704	}
705	
706	#[derive(Clone, Debug, PartialEq, Eq)]
707	pub struct SpecRewrite {
708	    pub key: RewriteKey,
709	    pub dependency: PackageId,
710	    pub from: DepSpec,
711	    pub to: DepSpec,
712	}
713	
714	pub enum RewriteOutcome {
715	    Rewritten(DepSpec),
716	    LeftAlone(Diagnostic),
717	}
718	
719	/// Rewrites one dependency edge toward `new`. A range a consumer's published manifest would keep excluding `new`
720	/// stops the run; only a dev dependency, which consumers never install, is left alone with a warning.
721	pub(crate) fn rewrite_edge(
722	    edge: &DepEdge,
723	    new: ConvergedTarget<'_>,
724	    cfg: &CascadeConfig,
725	) -> Result<RewriteOutcome, GraphError> {
726	    let eco = manifest_ecosystem(&edge.from_manifest);
727	    match rewrite_spec(&edge.spec, new, eco, cfg) {
728	        RewriteOutcome::LeftAlone(_) if edge.kind != DepKind::Dev => Err(GraphError::UnrewritableRange {
729	            dependent: edge.from.display_name(),
730	            dependency: edge.to.display_name(),
731	            spec: edge.spec.render(),
732	            version: new.version().render().to_string(),
733	            manifest: edge.from_manifest.display().to_string(),
734	        }),
735	        outcome => Ok(outcome),
736	    }
737	}
738	
739	pub(crate) fn rewrite_spec(
740	    original: &DepSpec,
741	    new: ConvergedTarget<'_>,
742	    eco: Ecosystem,
743	    cfg: &CascadeConfig,
744	) -> RewriteOutcome {
745	    let new = new.version();
746	    if !cfg.preserve_npm_ranges && eco == Ecosystem::Npm && !matches!(original, DepSpec::WorkspaceProtocol(_)) {
747	        return RewriteOutcome::Rewritten(DepSpec::Exact(new.clone()));
748	    }
749	
750	    // A rewrite that still excludes `new` is no rewrite: the dependent would publish a range its dependency cannot meet.
751	    match callisto_manifests::round_trip(eco, original, new)
752	        .filter(|rewritten| matches!(coverage(rewritten, new), Ok(Coverage::Covers | Coverage::Unknown)))
753	    {
754	        Some(rewritten) => RewriteOutcome::Rewritten(rewritten),
755	        _ => RewriteOutcome::LeftAlone(Diagnostic {
756	            code: DiagnosticCode::RangeNotRoundTrippable,
757	            severity: DiagnosticSeverity::Warning,
758	            message: format!(
759	                "spec `{}` could not be round-tripped toward version `{}`",
760	                original.render(),
761	                new.render()
762	            ),
763	            package: None,
764	            path: None,
765	            governed_by: Some(ConfigKey::CASCADE_PRESERVE_NPM_RANGES),
766	            escalated_by: None,
767	        }),
768	    }
769	}
