    let seed = BTreeMap::from([(upstream.clone(), Severity::Major)]);
    let mut base: BTreeMap<_, _> = [&upstream, &mid, &lib_a]
        .into_iter()
        .map(|id| (id.clone(), Version::semver(1, 0, 0)))
