struct IndexedGraph {
    packages: Vec<Package>,
    dependents: BTreeMap<PackageId, Vec<DepEdge>>,
    dependencies: BTreeMap<PackageId, Vec<DepEdge>>,
}

impl DependencyResolver for IndexedGraph {
    fn packages(&self) -> impl Iterator<Item = &Package> {
        self.packages.iter()
    }
    fn dependencies_of(&self, id: &PackageId) -> impl Iterator<Item = &DepEdge> {
        self.dependencies.get(id).into_iter().flatten()
    }
    fn dependents_of(&self, id: &PackageId) -> impl Iterator<Item = &DepEdge> {
        self.dependents.get(id).into_iter().flatten()
    }
}

#[test]
fn tmp_chain_timing() {
    let n = 500;
    let ids: Vec<PackageId> = (0..n).map(|i| PackageId::parse(&format!("pkg-{i:03}")).unwrap()).collect();
    let mut dependents: BTreeMap<PackageId, Vec<DepEdge>> = BTreeMap::new();
    let mut dependencies: BTreeMap<PackageId, Vec<DepEdge>> = BTreeMap::new();
    for i in 0..n - 1 {
        let edge = make_dep_edge(&ids[i], &ids[i + 1], "=1.0.0", Ecosystem::Cargo);
        dependents.entry(ids[i + 1].clone()).or_default().push(edge.clone());
        dependencies.entry(ids[i].clone()).or_default().push(edge);
    }
    let graph = IndexedGraph { packages: ids.iter().map(bare_package).collect(), dependents, dependencies };
    let base: BTreeMap<_, _> = ids.iter().map(|id| (id.clone(), Version::semver(1, 0, 0))).collect();
    let seed = BTreeMap::from([(ids[n - 1].clone(), Severity::Major)]);
    let cfg = CascadeConfig { mode: CascadeMode::OutOfRange, bump_severity: CascadeBumpSeverity::Patch, peer_escalation: true, preserve_npm_ranges: false };
    let reasons = BTreeMap::new();
    let identity = IdentityIndex::default();
    let tags = TagIndex::empty();
    let groups = GroupTable::default();
    let mut times = Vec::new();
    for _ in 0..5 {
        let start = std::time::Instant::now();
        let out = run_cascade(CascadeInput { graph: &graph, groups: &groups, cfg: &cfg, seed: &seed, reasons: &reasons, base: &base, pre: None, tags: &tags, identity: &identity }).unwrap();
        times.push(start.elapsed());
        assert_eq!(out.severities.len(), n);
    }
    times.sort();
    eprintln!("TIMING chain {n}: median {:?}", times[2]);
}
